};

/**
 * Molecule — the PDP meta block: the model line and the style code, in the order the design
 * places them beneath the accordions at the bottom of the info column.
 *
 * Both children already collapse on their own, so this exists for the spacing: the recipe owns
 * the 28px above the block and the 28px between its two rows.
 */
export const ZimmProductMeta = ({ modelInfo, styleCode }: ZimmProductMetaProps) => {
  const styles = useMultiStyleConfig(ZIMM_PRODUCT_META_RECIPE, {});

  // LOAD-BEARING, not a redundant echo of the children's own guards. Every other collapse in
  // ui-kits/ happens in an atom and the parent spaces whatever rendered with `gap` alone —
  // zimmProductContent.css.ts documents exactly that, and it works because a `gap` applies only
  // between rendered items, so an all-null column measures zero. This recipe also carries a
  // `paddingTop`, and padding is unconditional: without this guard, a product with neither a
  // style code nor model copy would still push 28px of empty space below the accordions.
  //
  // The predicate deliberately repeats zimmProductModelInfo/index.tsx:19's
  // `isBlankRichText(modelInfo)`. DRY holds at the logic level — `isBlankRichText`
  // (app/utils/richText.tsx) is the one shared implementation — so what repeats is the
  // *decision* about what counts as absent. If the atom's guard ever changes, this must follow.
  if (isBlankRichText(modelInfo) && !styleCode) return null;

  return (
    <chakra.div __css={styles.root} data-testid="product-meta">
      <ZimmProductModelInfo modelInfo={modelInfo} />
      <ZimmProductStyleCode value={styleCode} />
    </chakra.div>
  );
};

