import React from 'react';
import { chakra, useStyleConfig } from '@chakra-ui/react';
import { ZimmProductName } from 'app/components/ui-kits/atoms/zimmProductName';
import { ZimmProductPrice } from 'app/components/ui-kits/atoms/zimmProductPrice';
import { ZimmProductDescription } from 'app/components/ui-kits/atoms/zimmProductDescription';

const ZIMM_PRODUCT_CONTENT_RECIPE = 'ZimmProductContent';

type ZimmProductContentProps = {
  /** The product's display name. */
  name: string;
  /**
   * Heading level for the name. Passed through rather than fixed here so the caller keeps
   * control of the page's heading outline — see `ZimmProductName`.
   */
  headingLevel: 'h1' | 'h2' | 'h3';
  /**
   * Price, already formatted for the storefront's locale and currency by the caller. Optional
   * for the same reason as `description`: `ZimmProductPrice` renders nothing when the value is
   * absent or empty, so the group's `gap` collapses to whatever actually rendered.
   */
  price?: string;
  /** Long description as authored in Business Manager. Omitted when the product has none. */
  description?: string;
};

/**
 * Molecule — the PDP text group: name, price, description.
 *
 * Model copy and the style code are deliberately *not* here. The design places them at the
 * bottom of the column, after the accordions, so the page positions them itself rather than
 * this molecule holding them and then having to unpick the order.
 */
export const ZimmProductContent = ({ name, headingLevel, price, description }: ZimmProductContentProps) => {
  const styles = useStyleConfig(ZIMM_PRODUCT_CONTENT_RECIPE, {});

  return (
    <chakra.div __css={styles} data-testid="product-content">
      <ZimmProductName name={name} as={headingLevel} />
      <ZimmProductPrice price={price} />
      <ZimmProductDescription description={description} />
    </chakra.div>
  );
};

=== zimmProductPrice/index.tsx ===
import React from 'react';
import { chakra, useStyleConfig } from '@chakra-ui/react';

const ZIMM_PRODUCT_PRICE_RECIPE = 'ZimmProductPrice';

type ZimmProductPriceProps = {
  /**
   * The price, already formatted for the storefront's locale and currency by the caller
   * (`intl.formatNumber` at the page). This atom does no formatting of its own so it stays
   * usable from Storybook without an intl provider.
   *
   * Optional because the page's mapper resolves an absent price to `''` rather than to a
   * formatted `NaN` — see `pages/product-detail/productInfo.ts`'s `selectPdpProductInfo` and
   * the assertion it carries in `productInfo.test.ts`. That empty string reaches this atom
   * unchanged and the decision not to render is taken here.
   */
  price?: string;
  /** Reserved for SFCC-194's was/now treatment; only `default` is implemented today. */
  variant?: 'default';
};

/**
 * Atom — the single, full product price. Styling lives in `zimmProductPrice.css.ts` and is
 * consumed through the theme, per the one-canonical-styling-surface rule.
 *
 * Renders nothing when there is no price, so a caller can place it unconditionally — the same
 * contract as `ZimmProductDescription`. Rendering an empty `<p>` instead would still take a
 * flex `gap` in `ZimmProductContent`'s column, leaving a hole where the price should be.
 */
export const ZimmProductPrice = ({ price, variant = 'default' }: ZimmProductPriceProps) => {
  // Guard below the hook, never above it: an early return before `useStyleConfig` makes the
  // hook call conditional, which `react-hooks/rules-of-hooks` reports as an error rather than a
  // warning. Same ordering as `ZimmProductDescription` and `ZimmProductStyleCode`.
  const styles = useStyleConfig(ZIMM_PRODUCT_PRICE_RECIPE, { variant });
  if (!price) return null;

  return (
    <chakra.p __css={styles} textStyle="price" data-testid="product-price">
      {price}
    </chakra.p>
  );
};

